<?php $q=mysqli_query($koneksi,"SELECT p.*,a.namaasal,u.username FROM peminjam p LEFT JOIN asal a ON a.idasal=p.idasal LEFT JOIN user u ON u.iduser=p.iduser ORDER BY p.idpeminjam DESC"); ?>
